procedure.header:
#include "autopilot.h"
#include "firmwares/fixedwing/guidance/energy_ctrl.h"
#include "modules/digital_cam/dc.h"
#include "modules/digital_cam/uart_cam_ctrl.h"
#include "modules/nav/nav_mission4_geofence.h"

/* Offset of the MS plan's origin in this plan's frame (UTM, metres).
   Position in the MS frame = position here - offset. */
#define MISSION2_MS_FRAME_DX (-24.923f)
#define MISSION2_MS_FRAME_DY (233.862f)

/* Buffered Strasbourg flyzone check (hexagon + MISSION4_GEOFENCE_BUFFER,
   polygon in nav_mission4_geofence.h is in the MS frame). */
static inline bool mission2_in_flyzone_safe(float x, float y)
{
  return mission4_in_strasbourg_safe(x - MISSION2_MS_FRAME_DX, y - MISSION2_MS_FRAME_DY);
}

/* digital_cam_uart camera mask for this mission: LWIR only (bit 2; bit 0
   CHDK, bit 1 AI cam, bit 3 EARcam). The airframe's startup mask is 6
   (AI cam + LWIR). */
#define MISSION2_CAMERA_MASK_LWIR 4

/* ---- Line / turn sequencer (replaces nav_survey_poly_osam here) ---------
   The lines are ~19 m apart (3 over the ~57 m wide zone) but the Talon
   needs a ~30 m turn radius. One circle can only join two neighbouring
   lines if they are 2 R apart, so nav_survey_poly_osam's clamped circle
   left the aircraft INSIDE its turn circle and it wandered out to it, and
   its entry circle was half the spacing (~10 m), unflyable.

   Here every turn is a "bulb" of two circles of radius R, all joins
   tangent:
     1. a quarter circle turning TOWARDS the next line,
     2. a loop the other way round that ends exactly ON the next line,
        heading along it, 2 R past the end of the line just flown.
   The loops lie on the sweep side, away from the lines already flown.

   Entry: an ANTICLOCKWISE circle tangent to the start of line 1, `lead`
   metres before the zone. The aircraft circles there until it is at survey
   height, then leaves it tangentially onto line 1.

   Lines alternate direction. The sweep goes east (the across-line normal
   with positive x) and line 1 is flown with the sweep side on its right,
   so the anticlockwise entry circle sits outside the zone. Lines end
   `overrun` metres past the zone before turning. The survey altitude is
   held throughout. */
#define MISSION2_MAX_LINES 8
#define MISSION2_PH_ENTRY 0
#define MISSION2_PH_LINE 1
#define MISSION2_PH_TURN 2
#define MISSION2_PH_LOOP 3
#define MISSION2_PH_DONE 4

struct mission2_survey {
  int n, k, phase;          /* lines, current line, phase */
  float ux, uy, nx, ny;     /* line-1 direction, sweep direction (unit) */
  float s, r, alt;          /* spacing, turn radius, survey altitude */
  float sx[MISSION2_MAX_LINES], sy[MISSION2_MAX_LINES];
  float ex[MISSION2_MAX_LINES], ey[MISSION2_MAX_LINES];
  float cx, cy, rad;        /* current circle; rad positive = clockwise */
  float last_ang, turned, need, target_ang;
  float sg;                 /* +1: next line on the right of this line */
  uint8_t circle_wp;        /* shows the current circle centre in the GCS */
};

/* One state per build: a static array, not the address-of form (XML). */
static inline struct mission2_survey *mission2_st(void)
{
  static struct mission2_survey st[1];
  return st;
}

static inline float mission2_wrap_pi(float a)
{
  while (!signbit(a - (float)M_PI)) { a -= 2.0f * (float)M_PI; }
  while (signbit(a + (float)M_PI)) { a += 2.0f * (float)M_PI; }
  return a;
}

static inline float mission2_wrap_2pi(float a)
{
  while (signbit(a)) { a += 2.0f * (float)M_PI; }
  while (!signbit(a - 2.0f * (float)M_PI)) { a -= 2.0f * (float)M_PI; }
  return a;
}

/* Start following circle (cx, cy, rad) until `need` radians have been
   travelled round it in its own direction. */
static inline void mission2_start_circle(struct mission2_survey *m, float cx, float cy,
    float rad, float need)
{
  m[0].cx = cx;
  m[0].cy = cy;
  m[0].rad = rad;
  m[0].need = need;
  m[0].turned = 0.0f;
  m[0].last_ang = atan2f(stateGetPositionEnu_f()[0].y - cy, stateGetPositionEnu_f()[0].x - cx);
  waypoints[m[0].circle_wp].x = cx;
  waypoints[m[0].circle_wp].y = cy;
}

/* Fly the current circle and add up the angle travelled round it. */
static inline void mission2_fly_circle(struct mission2_survey *m)
{
  nav_circle_XY(m[0].cx, m[0].cy, m[0].rad);
  float a = atan2f(stateGetPositionEnu_f()[0].y - m[0].cy, stateGetPositionEnu_f()[0].x - m[0].cx);
  float d = mission2_wrap_pi(a - m[0].last_ang);
  if (!signbit(m[0].rad)) { d = -d; }   /* clockwise: the angle decreases */
  m[0].turned += d;
  m[0].last_ang = a;
}

/* Lay out the lines over the convex quadrilateral first_wp..first_wp+3,
   parallel to its longest edge, the fewest equal strips no wider than
   max_sweep (outer lines half a spacing from the edges). Returns the
   number of lines. entry_wp is set to the entry circle centre. */
static inline uint8_t mission2_survey_setup(uint8_t first_wp, float max_sweep, float overrun,
    float lead, float r, float alt, uint8_t entry_wp, uint8_t circle_wp)
{
  struct mission2_survey *m = mission2_st();
  uint8_t i;
  int k;
  float best = -1.0f, bdx = 1.0f, bdy = 0.0f;
  for (i = 0; i != 4; i++) {
    uint8_t a = first_wp + i;
    uint8_t b = first_wp + ((i + 1) % 4);
    float dx = waypoints[b].x - waypoints[a].x;
    float dy = waypoints[b].y - waypoints[a].y;
    float d2 = dx * dx + dy * dy;
    if (!signbit(d2 - best)) { best = d2; bdx = dx; bdy = dy; }
  }
  float len = sqrtf(best);
  if (signbit(len - 0.001f)) { len = 1.0f; }
  /* sweep direction: across the lines, towards the east */
  float nx = -bdy / len, ny = bdx / len;
  if (signbit(nx)) { nx = -nx; ny = -ny; }
  /* line-1 direction with the sweep side on its right: right(u) = n */
  float ux = -ny, uy = nx;

  float T[4], A[4];
  float lo = 0.0f, hi = 0.0f;
  for (i = 0; i != 4; i++) {
    T[i] = waypoints[first_wp + i].x * nx + waypoints[first_wp + i].y * ny;
    A[i] = waypoints[first_wp + i].x * ux + waypoints[first_wp + i].y * uy;
    if (i == 0) { lo = T[i]; hi = T[i]; }
    if (signbit(T[i] - lo)) { lo = T[i]; }
    if (!signbit(T[i] - hi)) { hi = T[i]; }
  }
  float width = hi - lo;
  if (signbit(max_sweep - 1.0f)) { max_sweep = 1.0f; }
  /* -0.001: a width of exactly k strips must give k lines, not k+1 */
  float nl = ceilf(width / max_sweep - 0.001f);
  if (signbit(nl - 1.0f)) { nl = 1.0f; }
  if (signbit((float)MISSION2_MAX_LINES - nl)) { nl = (float)MISSION2_MAX_LINES; }
  int N = (int)nl;
  float s = width / nl;

  for (k = 0; k != N; k++) {
    float Tk = lo + ((float)k + 0.5f) * s;
    float amin = 1e9f, amax = -1e9f;
    for (i = 0; i != 4; i++) {
      uint8_t j = (i + 1) % 4;
      float dt = T[j] - T[i];
      if (signbit(fabsf(dt) - 0.001f)) { continue; }
      float f = (Tk - T[i]) / dt;
      if (signbit(f) || signbit(1.0f - f)) { continue; }
      float Ak = A[i] + f * (A[j] - A[i]);
      if (signbit(Ak - amin)) { amin = Ak; }
      if (signbit(amax - Ak)) { amax = Ak; }
    }
    float a0, a1;
    if (k % 2 == 0) {   /* along line-1 direction */
      a0 = amin - ((k == 0) ? lead : overrun);
      a1 = amax + overrun;
    } else {            /* back the other way */
      a0 = amax + overrun;
      a1 = amin - overrun;
    }
    m[0].sx[k] = a0 * ux + Tk * nx;
    m[0].sy[k] = a0 * uy + Tk * ny;
    m[0].ex[k] = a1 * ux + Tk * nx;
    m[0].ey[k] = a1 * uy + Tk * ny;
  }

  m[0].n = N;
  m[0].k = 0;
  m[0].ux = ux;
  m[0].uy = uy;
  m[0].nx = nx;
  m[0].ny = ny;
  m[0].s = s;
  m[0].r = r;
  m[0].alt = alt;
  m[0].circle_wp = circle_wp;

  /* Anticlockwise entry circle on the left of line 1, tangent at its start. */
  float ecx = m[0].sx[0] - r * uy;
  float ecy = m[0].sy[0] + r * ux;
  m[0].target_ang = atan2f(ny, nx);   /* line-1 start seen from the centre */
  mission2_start_circle(m, ecx, ecy, -r, 0.0f);
  waypoints[entry_wp].x = ecx;
  waypoints[entry_wp].y = ecy;
  m[0].phase = MISSION2_PH_ENTRY;
  return (uint8_t)N;
}

/* Run the survey; FALSE when the last line is done. */
static inline bool mission2_survey_run(void)
{
  struct mission2_survey *m = mission2_st();
  int k = m[0].k;
  NavVerticalAutoThrottleMode(0.);
  NavVerticalAltitudeMode(m[0].alt, 0.);
  float px = stateGetPositionEnu_f()[0].x;
  float py = stateGetPositionEnu_f()[0].y;

  if (m[0].phase == MISSION2_PH_ENTRY) {
    mission2_fly_circle(m);
    /* leave at the tangent point, once at height and on the circle */
    float cur = atan2f(py - m[0].cy, px - m[0].cx);
    float togo = mission2_wrap_2pi(m[0].target_ang - cur);   /* anticlockwise */
    float dist = sqrtf((px - m[0].cx) * (px - m[0].cx) + (py - m[0].cy) * (py - m[0].cy));
    bool at_alt = !signbit(GetPosAlt() - (m[0].alt - 3.0f));
    bool on_circle = signbit(fabsf(dist - m[0].r) - 10.0f);
    /* nested, not the logical-and form: a raw ampersand is not valid XML */
    if (at_alt) {
      if (on_circle) {
        if (signbit(togo - RadOfDeg(10.0f))) { m[0].phase = MISSION2_PH_LINE; }
      }
    }
    return true;
  }

  if (m[0].phase == MISSION2_PH_LINE) {
    nav_route_xy(m[0].sx[k], m[0].sy[k], m[0].ex[k], m[0].ey[k]);
    if (nav_approaching_xy(m[0].ex[k], m[0].ey[k], m[0].sx[k], m[0].sy[k], 0.)) {
      if (k + 1 == m[0].n) {
        m[0].phase = MISSION2_PH_DONE;
        return false;
      }
      /* quarter circle towards the next line (always on the sweep side) */
      m[0].sg = (k % 2 == 0) ? 1.0f : -1.0f;   /* +1: next line on the right */
      mission2_start_circle(m, m[0].ex[k] + m[0].r * m[0].nx, m[0].ey[k] + m[0].r * m[0].ny,
                            m[0].sg * m[0].r, 0.5f * (float)M_PI);
      m[0].phase = MISSION2_PH_TURN;
    }
    return true;
  }

  if (m[0].phase == MISSION2_PH_TURN) {
    mission2_fly_circle(m);
    if (!signbit(m[0].turned - (m[0].need - RadOfDeg(5.0f)))) {
      /* loop the other way, ending on the next line 2 R past this line's end */
      float dx = m[0].ex[k] - m[0].sx[k], dy = m[0].ey[k] - m[0].sy[k];
      float dl = sqrtf(dx * dx + dy * dy);
      if (signbit(dl - 0.001f)) { dl = 1.0f; }
      dx /= dl;
      dy /= dl;
      float r = m[0].r;
      float lcx = m[0].ex[k] + (m[0].s + r) * m[0].nx + 2.0f * r * dx;
      float lcy = m[0].ey[k] + (m[0].s + r) * m[0].ny + 2.0f * r * dy;
      float rad = -m[0].sg * r;
      float exit_ang = atan2f(-m[0].ny, -m[0].nx);
      float cur = atan2f(py - lcy, px - lcx);
      float need = signbit(rad) ? mission2_wrap_2pi(exit_ang - cur) : mission2_wrap_2pi(cur - exit_ang);
      if (signbit(need - RadOfDeg(30.0f))) { need += 2.0f * (float)M_PI; }
      mission2_start_circle(m, lcx, lcy, rad, need);
      m[0].phase = MISSION2_PH_LOOP;
    }
    return true;
  }

  if (m[0].phase == MISSION2_PH_LOOP) {
    mission2_fly_circle(m);
    if (!signbit(m[0].turned - (m[0].need - RadOfDeg(3.0f)))) {
      m[0].k = k + 1;
      m[0].phase = MISSION2_PH_LINE;
    }
    return true;
  }

  return false;
}

/* Line direction of the survey: the longest edge of the polygon, as an
   atan(dy/dx) angle in degrees (for the camera course gate). */
static inline float mission2_longest_edge_angle(uint8_t first_wp, uint8_t n)
{
  uint8_t i;
  float best = -1.0f;
  float bdx = 1.0f, bdy = 0.0f;
  for (i = 0; i != n; i++) {
    uint8_t a = first_wp + i;
    uint8_t b = first_wp + ((i + 1) % n);
    float dx = waypoints[b].x - waypoints[a].x;
    float dy = waypoints[b].y - waypoints[a].y;
    float d2 = dx * dx + dy * dy;
    if (!signbit(d2 - best)) { best = d2; bdx = dx; bdy = dy; }
  }
  if (signbit(fabs(bdx) - 0.000001f)) { bdx = 0.000001f; }
  return DegOfRad(atan(bdy / bdx));
}

/* tan(HFOV / 2) for the 40 x 30 deg LWIR lens: swath = 2 * height * this */
#define MISSION2_TAN_HALF_HFOV 0.36397f

/* True if (x, y) is at least `margin` metres inside the convex polygon
   waypoints[first_wp .. first_wp+n-1]. The winding is taken from the signed
   area, so a relabelled or re-dragged zone needs no code change. */
static inline bool mission2_inside_zone(uint8_t first_wp, uint8_t n, float x, float y, float margin)
{
  uint8_t i;
  float area2 = 0.0f;
  for (i = 0; i != n; i++) {
    uint8_t a = first_wp + i;
    uint8_t b = first_wp + ((i + 1) % n);
    area2 += waypoints[a].x * waypoints[b].y - waypoints[b].x * waypoints[a].y;
  }
  float wind = 1.0f;
  if (signbit(area2)) { wind = -1.0f; }

  for (i = 0; i != n; i++) {
    uint8_t a = first_wp + i;
    uint8_t b = first_wp + ((i + 1) % n);
    float ex = waypoints[b].x - waypoints[a].x;
    float ey = waypoints[b].y - waypoints[a].y;
    float len = sqrtf(ex * ex + ey * ey);
    if (signbit(len - 0.001f)) { continue; }
    /* signed distance from this edge, positive towards the inside */
    float dist = wind * (ex * (y - waypoints[a].y) - ey * (x - waypoints[a].x)) / len;
    if (signbit(dist - margin)) { return false; }
  }
  return true;
}

/* Shoot ONLY inside the fire zone (aircraft position now AND `lookahead`
   seconds ahead along the ground velocity, covering the lag between this
   gate at 20 Hz and dc_periodic at 10 Hz), and only while the GROUND TRACK
   runs along the survey lines (either direction, within
   max_course_err_deg), so no frames come from turns or roll-outs. A frame
   taken just inside the edge still images 13.4 m past it along track, so
   edges stay covered.
   Sets dc_autoshoot directly: dc_stop() sends DC_INFO on every call and
   dc_distance() resets the last shot position.
   [0].x, not an arrow: a raw angle bracket in this header is invalid XML. */
static inline void mission2_shoot_in_zone(float max_roll_deg, uint8_t first_wp, uint8_t n, float lookahead,
    float max_course_err_deg)
{
  /* Roll no longer gates shots: the course check below does that job. */
  (void)max_roll_deg;
  bool shoot = true;
  float x = stateGetPositionEnu_f()[0].x;
  float y = stateGetPositionEnu_f()[0].y;
  float sx = stateGetSpeedEnu_f()[0].x;
  float sy = stateGetSpeedEnu_f()[0].y;
  float ax = x + sx * lookahead;
  float ay = y + sy * lookahead;
  if (!mission2_inside_zone(first_wp, n, x, y, 0.0f)) { shoot = false; }
  if (!mission2_inside_zone(first_wp, n, ax, ay, 0.0f)) { shoot = false; }
  float line_angle = mission2_longest_edge_angle(first_wp, n);
  float track_err = fmod(fabs(DegOfRad(atan2f(sy, sx)) - line_angle), 180.0f);
  if (!signbit(track_err - 90.0f)) { track_err = 180.0f - track_err; }
  if (!signbit(track_err - max_course_err_deg)) { shoot = false; }
  if (shoot) {
    dc_autoshoot = DC_AUTOSHOOT_DISTANCE;
  } else {
    dc_autoshoot = DC_AUTOSHOOT_STOP;
  }
}
